-- Ce que la transaction vient de faire, avant de la valider.
SELECT count(*) FILTER (WHERE nom_fr IS NOT NULL) AS traduits,
       count(*) FILTER (WHERE nom_fr IS NULL)     AS restants,
       count(*)                                   AS total
FROM exercice WHERE source <> 'perso';

COMMIT;
